use vstd::prelude::*;

verus! {

/// Concatenate `a` followed by `b` (horizontal stack).
/// Produces a fresh vector; does not mutate inputs.
fn hstack(a: Vec<f32>, b: Vec<f32>) -> (res: Vec<f32>)
    ensures
        // Length is sum of lengths
        res@.len() == a@.len() + b@.len(),

        // Prefix equals `a`
        forall|i: int|
            0 <= i < a@.len() ==> res@[i] == a@[i],

        // Suffix equals `b` shifted by |a|
        forall|j: int|
            0 <= j < b@.len() ==> res@[a@.len() + j] == b@[j],

        // (Optional but useful) Result is exactly the sequence concatenation
        res@ == a@ + b@,
{
    let mut res: Vec<f32> = Vec::new();
    let mut i: usize = 0;

    while i < a.len()
        invariant
            i <= a.len(),
            res@ == a@.subrange(0, i as int),
    {
        res.push(a[i]);
        i += 1;
    }

    let mut j: usize = 0;
    while j < b.len()
        invariant
            j <= b.len(),
            res@ == a@ + b@.subrange(0, j as int),
    {
        res.push(b[j]);
        j += 1;
    }

    res
}

} // verus!